def compute_RHT_application(A_k, R_q):
    max_RHT = 0
    for tau_i in tasks_accessing(A_k, R_q):
        RHT_i = compute_RHT_task(tau_i, R_q)
        max_RHT = max(max_RHT, RHT_i)
    return max_RHT

def compute_direct_blocking(tau_i):
    DB = 0
    for R_q in resources_used_by(tau_i):
        max_cs = max(tau_j.Cs_q for tau_j in lower_priority_tasks(tau_i, R_q))
        DB += tau_i.n_i_q * max_cs
    return DB

def compute_Ilp_prime_IPIP(tau_i, Ilp_i, m):
    Ilp_prime = Ilp_i
    for R_q in resources_where_boost_equals_priority(tau_i):
        max_cs = max(tau_j.Cs_q for tau_j in lower_priority_tasks(tau_i, R_q))
        Ilp_prime += max_cs / m
    return Ilp_prime

def verify_minimum_boost_schedulable(A_k):
    # Assume A_k schedulable under PIP
    for R_q in global_resources(A_k):
        boost_q = ceiling(R_q)
    # Test schedulability with these boost levels
    return is_schedulable(A_k)  # Returns True

def find_pareto_optimal_boosts(A_k, global_resources):
    pareto_set = []
    for ordering in permutations(global_resources):
        allocation = optimize_boosts_in_order(A_k, ordering)
        if is_pareto_optimal(allocation, pareto_set):
            pareto_set.append(allocation)
    return pareto_set
